<script setup>
import { computed, onMounted, ref } from 'vue'
import { AlertTriangle, ChevronRight, Download, FileText, Leaf, LoaderCircle, Trash2 } from 'lucide-vue-next'
import { deleteGrowthHistory, getGrowthHistory, getGrowthHistoryItem, growthMediaUrl } from '../services/growthApi'

const history = ref([])
const selected = ref(null)
const loading = ref(true)
const error = ref('')
const selectedPlotHistory = computed(() => {
  if (!selected.value?.plot_id) return []
  return history.value.filter(item => item.plot_id === selected.value.plot_id).sort((a, b) => String(a.completed_at_utc || a.created_at_utc || '').localeCompare(String(b.completed_at_utc || b.created_at_utc || '')))
})

async function loadHistory() {
  loading.value = true
  try { history.value = await getGrowthHistory() } catch (caught) { error.value = caught.message || '历史记录读取失败。' } finally { loading.value = false }
}
async function openReport(item) {
  try { selected.value = await getGrowthHistoryItem(item.analysis_id); error.value = '' } catch (caught) { error.value = caught.message || '分析报告读取失败。' }
}
async function removeReport(item) {
  if (!window.confirm(`确定删除 ${item.analysis_id} 的分析记录吗？`)) return
  try { await deleteGrowthHistory(item.analysis_id); history.value = history.value.filter(entry => entry.analysis_id !== item.analysis_id); if (selected.value?.analysis_id === item.analysis_id) selected.value = null } catch (caught) { error.value = caught.message || '分析记录删除失败。' }
}
function exportReport() {
  if (!selected.value) return
  const blob = new Blob([JSON.stringify(selected.value, null, 2)], { type: 'application/json;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = `maishitong-report-${selected.value.analysis_id}.json`
  link.click()
  URL.revokeObjectURL(url)
}
onMounted(loadHistory)
</script>

<template>
  <div class="reports-page">
    <header class="reports-heading"><div><span class="reports-eyebrow">ANALYSIS ARCHIVE</span><h1>我的分析记录</h1><p>查看真实上传图片生成的长势分析结果和评价依据。</p></div><span class="reports-status"><span></span>{{ history.length }} 条记录</span></header>
    <p v-if="error" class="reports-error"><AlertTriangle :size="16" />{{ error }}</p>
    <div v-if="loading" class="reports-empty"><LoaderCircle class="spin" :size="22" />正在读取历史分析</div>
    <div v-else-if="!history.length" class="reports-empty"><FileText :size="35" /><strong>暂无历史分析</strong><span>完成一次真实小麦图片分析后，记录会显示在这里。</span></div>
    <section v-else class="reports-layout">
      <div class="report-list"><article v-for="item in history" :key="item.analysis_id" class="report-card" :class="{ active: selected?.analysis_id === item.analysis_id }" @click="openReport(item)"><div class="report-thumb"><img v-if="item.original_url" :src="growthMediaUrl(item.original_url)" alt="小麦分析原图" /><Leaf v-else :size="22" /></div><div class="report-card-copy"><strong>{{ item.vigor_level || '暂不评级' }}</strong><small>{{ item.completed_at_utc || item.created_at_utc }}</small><span>{{ item.vigor_score == null ? '综合分 —' : `综合分 ${Number(item.vigor_score).toFixed(1)}` }} · {{ item.reliability || '可靠性 —' }}</span></div><button class="report-delete" title="删除记录" @click.stop="removeReport(item)"><Trash2 :size="15" /></button><ChevronRight class="report-arrow" :size="16" /></article></div>
      <article v-if="selected" class="report-detail"><div class="report-detail-head"><h2><Leaf :size="18" />小麦植株分析</h2><div class="report-detail-actions"><span>{{ selected.evaluation_version || '历史记录' }}</span><button class="export-report" @click="exportReport"><Download :size="14" />导出 JSON</button></div></div><div class="detail-images"><img v-if="selected.original_url" :src="growthMediaUrl(selected.original_url)" alt="分析原图" /><img v-if="selected.overlay_url" :src="growthMediaUrl(selected.overlay_url)" alt="分析叠加图" /></div><div class="detail-score"><strong>{{ selected.vigor_score == null ? '—' : Number(selected.vigor_score).toFixed(1) }}</strong><span>{{ selected.vigor_level || '暂不评级' }}</span><small>可靠性：{{ selected.reliability || '—' }}</small></div><div class="detail-lines"><p><b>地块编号</b><span>{{ selected.plot_id || '未提供，不组成连续曲线' }}</span></p><p><b>植被覆盖率</b><span>{{ selected.vegetation_coverage?.percentage == null ? '—' : `${Number(selected.vegetation_coverage.percentage).toFixed(2)}%` }}</span></p><p><b>绿色程度评分</b><span>{{ selected.greenness_score == null ? '—' : Number(selected.greenness_score).toFixed(1) }}</span></p><p><b>空间均匀度评分</b><span>{{ selected.uniformity_score == null ? '—' : Number(selected.uniformity_score).toFixed(1) }}</span></p><p><b>生育期</b><span>{{ selected.growth_stage?.predicted_stage_name || (selected.growth_stage_status === 'GROWTH_STAGE_MODEL_UNAVAILABLE' ? '模型待验证' : '—') }}</span></p><p><b>使用算法</b><span>{{ selected.algorithm || '—' }}</span></p><p><b>评价规则</b><span>{{ selected.evaluation_version || '—' }}</span></p></div><div v-if="selected.plot_id" class="plot-trend"><div class="trend-title"><b>同一地块历史变化</b><small>{{ selectedPlotHistory.length }} 条记录</small></div><div v-if="selectedPlotHistory.length > 1" class="trend-list"><div v-for="item in selectedPlotHistory" :key="item.analysis_id" class="trend-row"><span>{{ item.completed_at_utc || item.created_at_utc }}</span><i :style="{ width: `${Math.max(0, Math.min(100, Number(item.vigor_score || 0)))}%` }"></i><b>{{ item.vigor_score == null ? '—' : Number(item.vigor_score).toFixed(1) }}</b><em>{{ item.vigor_level || '—' }}</em><small>{{ item.vegetation_coverage?.percentage == null ? '覆盖 —' : `覆盖 ${Number(item.vegetation_coverage.percentage).toFixed(1)}%` }} · {{ item.growth_stage?.predicted_stage_name || '阶段待验证' }}</small></div></div><p v-else class="trend-empty">同一地块还没有足够的历史记录，暂不绘制趋势。</p></div><div v-else class="trend-empty">当前记录未提供地块编号，系统不会把它与其他图片拼接成生长曲线。</div><div class="detail-notes"><div><b>主要优势</b><span v-for="item in (selected.strengths || [])" :key="item">{{ item }}</span></div><div><b>需要关注</b><span v-for="item in (selected.improvement_suggestions || [])" :key="item">{{ item }}</span></div></div></article><div v-else class="report-detail report-detail-empty"><FileText :size="30" /><span>选择一条历史记录查看完整分析。</span></div>
    </section>
  </div>
</template>

<style scoped>
